import{_ as r,o as a,c as n,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const b=JSON.parse('{"title":"Optimizing Scrub Performance- Balancing Scrub Speed Against Client I/O Demands - Ronen Friedman, IBM","description":"","frontmatter":{"title":"Optimizing Scrub Performance- Balancing Scrub Speed Against Client I/O Demands - Ronen Friedman, IBM","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-19T00:00:00.000Z","tags":["Ceph","Scrub","Performance Optimization","Distributed Storage","CephFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Optimizing_Scrub_Performance_-_Balancing_Scrub_Speed_Against_Client_I_O_Demands_-_Ronen_Friedman_IBM.md","filePath":"posts/2025/Optimizing_Scrub_Performance_-_Balancing_Scrub_Speed_Against_Client_I_O_Demands_-_Ronen_Friedman_IBM.md","lastUpdated":1780459816000}'),t={name:"posts/2025/Optimizing_Scrub_Performance_-_Balancing_Scrub_Speed_Against_Client_I_O_Demands_-_Ronen_Friedman_IBM.md"};function i(c,e,s,l,d,_){return a(),n("div",null,[...e[0]||(e[0]=[o('<h3 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h3><p>IBM的Ronen Friedman在会议上详细介绍了Ceph分布式存储系统中scrub操作的性能优化与调度改进方案。Friedman作为scrub模块的主要开发者，分享了如何减少scrub对客户端IO（尤其是延迟）的影响，并探讨了如何平衡scrub速度与客户端I/O需求。</p><h3 id="关键技术点" tabindex="-1">关键技术点 <a class="header-anchor" href="#关键技术点" aria-label="Permalink to &quot;关键技术点&quot;">​</a></h3><h4 id="scrub基础流程" tabindex="-1">Scrub基础流程 <a class="header-anchor" href="#scrub基础流程" aria-label="Permalink to &quot;Scrub基础流程&quot;">​</a></h4><ul><li><strong>资源预留</strong>：通过<code>osd_max_scrubs</code>参数限制并发scrub数量，Squid版本引入了新的scrub队列设计。</li><li><strong>监控工具</strong>：使用<code>ceph pg dump</code>和<code>ceph tell osd dump scrub reservations</code>等工具查看PG状态和OSD的scrub预留情况。</li><li><strong>性能计数器</strong>：提供scrub启动/失败次数等详细指标。</li></ul><h4 id="性能优化" tabindex="-1">性能优化 <a class="header-anchor" href="#性能优化" aria-label="Permalink to &quot;性能优化&quot;">​</a></h4><ul><li><strong>Chunk处理</strong>：每个chunk包含一定范围的对象，Squid版本增加了默认chunk大小，并在客户端写操作时中断scrub并减半chunk大小。</li><li><strong>IO密集型阶段</strong>：Deep scrub会读取所有数据和元数据，通过<code>osd_deep_scrub_stride</code>控制数据读取粒度。</li><li><strong>调度优化</strong>：使用mclock调度器精确控制scrub资源占用。</li></ul><h4 id="tentacle版本改进" tabindex="-1">Tentacle版本改进 <a class="header-anchor" href="#tentacle版本改进" aria-label="Permalink to &quot;Tentacle版本改进&quot;">​</a></h4><ul><li><strong>调度分离</strong>：解耦shallow scrub和deep scrub的调度，各自维护独立的状态记录。</li><li><strong>Deep Scrub调度</strong>：新参数<code>osd_deep_scrub_interval_cv</code>控制调度时间分布，健康警告基于<code>desired_interval * deep_scrub_ratio</code>。</li><li><strong>Shallow Scrub调度</strong>：保持原有<code>interval</code>和<code>randomization_ratio</code>参数，不再自动转换为deep scrub。</li></ul><h3 id="行动计划" tabindex="-1">行动计划 <a class="header-anchor" href="#行动计划" aria-label="Permalink to &quot;行动计划&quot;">​</a></h3><ul><li><strong>代码改进</strong>：修复chunk大小下限问题，优化scrub过程中的不必要yield点，完善性能计数器。</li><li><strong>参数调整建议</strong>：考虑增加<code>osd_deep_scrub_stride</code>，使用mclock时应自定义scrub资源分配，谨慎设置<code>osd_scrub_sleep</code>。</li><li><strong>监控建议</strong>：关注<code>scrub_chunk_selected</code>和<code>scrub_locked_objects</code>计数器，检查日志中的&quot;in progress&quot;提示信息。</li></ul><h3 id="遗留问题" tabindex="-1">遗留问题 <a class="header-anchor" href="#遗留问题" aria-label="Permalink to &quot;遗留问题&quot;">​</a></h3><ul><li>Preempt逻辑是否需要调整。</li><li>进一步优化EC pools的scrub性能参数。</li><li>完善mclock与scrub的集成体验。</li></ul><p>会议展示了Ceph在scrub性能优化方面的持续改进，特别是在Tentacle版本中引入的调度分离和更灵活的配置选项，将显著提升大规模生产环境的运维体验。</p>',14)])])}const p=r(t,[["render",i]]);export{b as __pageData,p as default};
